style.css:
/* Toxic Emerald | Roblox */

:root {
  /* cambia estos colores si te da la gana */
  --my-bg: #080d0a;
  --my-panel: #111b14;
  --my-green: #39ff88;
  --my-text: #e2f5e8;
}

/* fondo oscuro */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* enlaces verdes */
a {
  color: var(--my-green) !important;
}

/* campos oscuros */
input,
textarea,
select {
  background-color: var(--my-panel) !important;
  color: var(--my-text) !important;
  border: 1px solid #245c3a !important;
  border-radius: 8px !important;
}

/* botones con toque neón */
button {
  border-radius: 8px !important;
}

/* imágenes más suaves */
img {
  border-radius: 8px;
}
